const storedLocale = window.localStorage.getItem('30sales-locale');
const browserLocale = navigator.language.toLowerCase().startsWith('pt') ? 'pt-BR' : 'en';
const initialLocale = storedLocale === 'pt-BR' || storedLocale === 'en' ? storedLocale : browserLocale;
document.documentElement.lang = initialLocale;
void i18n.use(initReactI18next).init({ resources, lng: initialLocale, fallbackLng: 'en', interpolation: { escapeValue: false } });
i18n.on('languageChanged', (locale) => { window.localStorage.setItem('30sales-locale', locale); document.documentElement.lang = locale; });
export default i18n;
